export const BIN_COUNT = 32;

function assertBin(value: number, name: string): void {
  if (!Number.isInteger(value) || value < 0 || value >= BIN_COUNT) {
    throw new RangeError(`${name} must be an integer from 0 to ${BIN_COUNT - 1}`);
  }
}

export function selectStorageBin(
  occupied: readonly number[],
  preferred: readonly number[],
  scanStart = 0,
): number {
  assertBin(scanStart, "scanStart");
  occupied.forEach((value, index) => assertBin(value, `occupied[${index}]`));
  preferred.forEach((value, index) => assertBin(value, `preferred[${index}]`));

  const unavailable = new Set(occupied);
  for (const bin of preferred) {
    if (!unavailable.has(bin)) {
      return bin;
    }
  }

  for (let offset = 1; offset < BIN_COUNT; offset += 1) {
    const bin = (scanStart + offset) % BIN_COUNT;
    if (!unavailable.has(bin)) {
      return bin;
    }
  }
  throw new Error("No storage bin is available");
}

