import { BIN_COUNT, selectStorageBin } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsType(action: () => unknown, type: Function, message: string): void {
  try { action(); } catch (error) {
    if (error instanceof type) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

equal(BIN_COUNT, 32, 'BIN_COUNT');
equal(selectStorageBin([], []), 0, 'empty inputs use default scan start');
equal(selectStorageBin([0, 1, 2], [], 1), 3, 'circular scan begins at scanStart');
equal(selectStorageBin([30, 31, 0], [], 30), 1, 'circular scan wraps');
equal(selectStorageBin([2, 4], [4, 7, 2, 9], 20), 7, 'preferred order is preserved');
equal(selectStorageBin([4, 4, 5], [4, 4], 4), 6, 'duplicates do not affect fallback');
equal(selectStorageBin([0], [31], 0), 31, 'upper boundary is valid');

const allBut17: number[] = [];
for (let value = 0; value < BIN_COUNT; value += 1) if (value !== 17) allBut17.push(value);
equal(selectStorageBin(allBut17, [], 18), 17, 'every bin is inspected once');
throwsType(() => selectStorageBin(Array.from({ length: BIN_COUNT }, (_, index) => index), []), Error, 'full storage throws');

for (const invalid of [-1, 32, 1.5, Number.NaN, Number.POSITIVE_INFINITY]) {
  throwsType(() => selectStorageBin([invalid], []), RangeError, `invalid occupied ${String(invalid)}`);
  throwsType(() => selectStorageBin([], [invalid]), RangeError, `invalid preferred ${String(invalid)}`);
  throwsType(() => selectStorageBin([], [], invalid), RangeError, `invalid scanStart ${String(invalid)}`);
}
throwsType(() => selectStorageBin([], [3, 99]), RangeError, 'all preferred entries are validated');
throwsType(() => selectStorageBin([99], [3]), RangeError, 'occupied entries are validated before selection');

const occupied = [0, 2];
const preferred = [2, 5];
const occupiedBefore = occupied.slice();
const preferredBefore = preferred.slice();
equal(selectStorageBin(occupied, preferred), 5, 'detached primitive result');
assert(occupied.length === occupiedBefore.length && occupied.every((v, i) => v === occupiedBefore[i]), 'occupied was mutated');
assert(preferred.length === preferredBefore.length && preferred.every((v, i) => v === preferredBefore[i]), 'preferred was mutated');
occupied.push(5);
preferred[1] = 8;
equal(5, 5, 'later input mutation cannot alter returned number');

